// The port's half of the wind-and-sand package's recipe parity (PORT_PLAN.md 5.3, 5.5): the dunes recipe generated by
// the port end to end (api.js generate: the level plan, the recipe's prepare hook, run.js's level loop with this
// package's dune_field on every level, the end stages, the ring mesh), saved in the Terrain.save format and judged by
// the Blender edition's own judge (tests/judge/judge.mjs), for each variant and seed, as tests/wind_sand/
// blender_kinds.py makes Blender's.
//
//     deno run --config deno.json --frozen --unstable-webgpu --allow-all eidoverse/terrain/tests/wind_sand/recipe_runs.mjs
//          [--variants star,gsd,transverse,linear,barchan] [--seeds 1,2,3,4] [--quality draft] [--again]
//
// (from the repository root; behind $EIDO_GPU_WRAP on a shared machine). Writes tests/out/wind_sand/port_kinds/
// <variant>_s<seed>/terrain.npz + .json, verdict.json, run.json; a run already there is kept unless --again. The
// solvers' memos are cleared before every run (plan 5.4: aeolian.clearTiles), and the cache is off.

import * as G from '../../core/gpu.js';
import * as A from '../../solvers/aeolian.js';
import { generate } from '../../api.js';
import * as J from '../judge/judge.mjs';
import * as C from '../parity/_common.mjs';
import * as S from './_common.mjs';

export const GSD = { winds: [[282, 1.0], [102, 0.7], [192, 0.5]], sand_m: 40, spacing_m: 900, bed_relief_m: 30, sand_patchiness: 0.5 };
// the variants and their references (blender_kinds.py VARIANTS); size: the reference's extent (judge/refs.py)
export const VARIANTS = {
    star: { reference: 'namib_star_dunes', size: 8000.0, params: null },
    gsd: { reference: 'great_sand_dunes', size: 5000.0, params: GSD },
    transverse: { reference: 'white_sands', size: 3000.0, params: { kind: 'transverse' } },
    linear: { reference: 'namib_linear_dunes', size: 10000.0, params: { kind: 'linear' } },
    barchan: { reference: 'white_sands', size: 3000.0, params: { kind: 'barchan' } },
};
export const PORT_DIR = `${S.OUT}/port_kinds`;
export const BLENDER_DIR = `${S.OUT}/blender_kinds`;

/** One port run: generate, save, judge. Returns its run record. */
export async function portRun(variant, seed, opts = {}) {
    const v = VARIANTS[variant];
    const d = `${PORT_DIR}/${variant}_s${seed}`;
    Deno.mkdirSync(d, { recursive: true });
    A.clearTiles();
    const logs = [];
    const t0 = performance.now();
    const t = await generate({ recipe: 'dunes', size: v.size, seed, params: v.params, quality: opts.quality ?? 'draft', cache: false,
        log: (m) => logs.push(m) });
    const seconds = +((performance.now() - t0) / 1000).toFixed(2);
    await t.save(`${d}/terrain`);
    const levels = t.levels.map((lv) => String(lv));
    const info = { seconds: t.info?.seconds ?? null, skipped: t.info?.skipped_stages ?? [], warnings: t.info?.warnings ?? [] };
    t.dispose();
    A.clearTiles();
    const verdict = await J.judgeSave(`${d}/terrain`, { reference: v.reference, label: `dunes_${variant}_seed${seed}`, outDir: d });
    if (verdict) Deno.writeTextFileSync(`${d}/verdict.json`, JSON.stringify(verdict, null, 1));
    const run = { variant, seed, reference: v.reference, size: v.size, params: v.params, quality: opts.quality ?? 'draft', seconds,
        levels, info, log: logs.filter((m) => m.includes('aeolian') || m.includes('terrain.run')).slice(0, 60), judged: !!verdict,
        deno: Deno.version.deno, date: new Date().toISOString() };
    Deno.writeTextFileSync(`${d}/run.json`, JSON.stringify(run, null, 1));
    return run;
}

if (import.meta.main) {
    const args = [...Deno.args];
    const opt = (n, dflt) => { const i = args.indexOf(n); return i >= 0 ? args.splice(i, 2)[1] : dflt; };
    const flag = (n) => { const i = args.indexOf(n); if (i < 0) return false; args.splice(i, 1); return true; };
    const variants = opt('--variants', Object.keys(VARIANTS).join(',')).split(',');
    const seeds = opt('--seeds', '1,2,3,4').split(',').map(Number);
    const quality = opt('--quality', 'draft'), again = flag('--again');
    await G.init();
    for (const variant of variants) {
        for (const seed of seeds) {
            const d = `${PORT_DIR}/${variant}_s${seed}`;
            if (!again && C.readJson(`${d}/run.json`)?.judged) {
                console.log(`[recipe_runs] ${variant} seed ${seed}: done already`);
                continue;
            }
            try {
                const r = await portRun(variant, seed, { quality });
                const v = C.readJson(`${d}/verdict.json`);
                const judged = v ? v.rows.filter((x) => x.passed !== null) : [];
                console.log(`[recipe_runs] ${variant} seed ${seed}: ${r.seconds} s, ${r.reference} ` +
                    (v ? `${judged.filter((x) => x.passed).length}/${judged.length} bands` : 'not judged'));
            } catch (e) {
                console.log(`[recipe_runs] ${variant} seed ${seed} FAILED: ${e.stack ?? e}`);
                Deno.writeTextFileSync(`${d}/failed.txt`, String(e.stack ?? e));
            }
        }
    }
    G.shutdown();
}
